package com.edgecloud.alert.service;
import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import java.util.*; import org.junit.jupiter.api.*; import com.edgecloud.alert.dto.*; import com.edgecloud.alert.entity.*; import com.edgecloud.alert.exception.*; import com.edgecloud.alert.repository.*;
class EscalationPolicyServiceTest {private EscalationPolicyRepository policies=mock(EscalationPolicyRepository.class);private EscalationPolicyService service=new EscalationPolicyService(policies,mock(AlertEscalationHistoryRepository.class),mock(AlertEventRepository.class));private UUID project=UUID.randomUUID();
 @Test void rejectsDuplicateAndNonIncreasingLevels(){var duplicate=new EscalationPolicyRequest("Ops",true,List.of(new EscalationPolicyRequest.Level(1,10,Severity.LOW,true),new EscalationPolicyRequest.Level(1,20,Severity.HIGH,true)));assertThatThrownBy(()->service.save(project,duplicate)).isInstanceOf(EscalationPolicyValidationException.class);var reversed=new EscalationPolicyRequest("Ops",true,List.of(new EscalationPolicyRequest.Level(1,20,Severity.LOW,true),new EscalationPolicyRequest.Level(2,10,Severity.HIGH,true)));assertThatThrownBy(()->service.save(project,reversed)).isInstanceOf(EscalationPolicyValidationException.class);}
 @Test void persistsOrderedValidPolicy(){var request=new EscalationPolicyRequest("Ops",true,List.of(new EscalationPolicyRequest.Level(1,60,Severity.MEDIUM,true),new EscalationPolicyRequest.Level(2,120,Severity.HIGH,true)));when(policies.findByProjectId(project)).thenReturn(Optional.empty());when(policies.save(any())).thenAnswer(i->i.getArgument(0));var response=service.save(project,request);assertThat(response.levels()).extracting(EscalationPolicyResponse.Level::levelNumber).containsExactly(1,2);}
}
